record_usage: key model: model tokens: tokens
	(state at: 'calls' ifAbsentPut: [ OrderedCollection new ])
		add: (Dictionary new
			at: 'key' put: key;
			at: 'model' put: model;
			at: 'tokens' put: tokens;
			yourself).
	^ self usage: key

